begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('c1100000-0000-4000-8000-000000000001','authenticated','authenticated','review-a@example.test','',now(),'{}','{"name":"Review A","company_name":"Review A"}',now(),now()),
('c1100000-0000-4000-8000-000000000002','authenticated','authenticated','review-b@example.test','',now(),'{}','{"name":"Review B","company_name":"Review B"}',now(),now()),
('c1100000-0000-4000-8000-000000000003','authenticated','authenticated','review-customer@example.test','',now(),'{}','{"name":"Review Customer","company_name":"Review Customer"}',now(),now());
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('c11.a',private.current_company_id(),true);
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('c11.b',private.current_company_id(),true);
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into public.customers(id,company_id,name,document,phone,email) values('c11-customer',current_setting('c11.a'),'Maria Privada Silva','12345678900','81999999999','private@example.test');
insert into public.store_customer_accounts(company_id,customer_id,auth_user_id) values(current_setting('c11.a'),'c11-customer','c1100000-0000-4000-8000-000000000003');
insert into public.products(id,company_id,name,description,sku,pricing_type,sales_price,base_cost,active,catalog_active,image_url) values
('c11-product',current_setting('c11.a'),'QA Review Product','Public product','C11A','unidade',10,1,true,true,'https://example.test/a.png');
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into public.products(id,company_id,name,description,sku,pricing_type,sales_price,base_cost,active,catalog_active,image_url) values
('c11-other',current_setting('c11.b'),'Other tenant product','Other product','C11B','unidade',10,1,true,true,null);
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,paid_amount) select 'c11-'||n,current_setting('c11.a'),'c11-customer','Maria Privada Silva','QA-C11-'||n,case when n='pending' then 'aguardando_pagamento' else 'finalizado' end,10,0 from unnest(array['one','two','pending']) n;
insert into public.order_items(id,order_id,product_id,product_name,quantity,unit_price,total_price) select 'c11-item-'||n,'c11-'||n,'c11-product','QA Review Product',1,10,10 from unnest(array['one','two','pending']) n;
create function pg_temp.c11_invite(o text) returns jsonb language sql as $$select public.product_reviews_command('invite',jsonb_build_object('order_id','c11-'||o,'product_id','c11-product'))$$;
create function pg_temp.c11_moderate(action text,id uuid) returns jsonb language sql as $$select public.product_reviews_command(action,jsonb_build_object('id',id,'revision',(select revision from public.product_reviews where product_reviews.id=$2),'reason','Motivo QA'))$$;
grant execute on function pg_temp.c11_invite(text),pg_temp.c11_moderate(text,uuid) to authenticated;
select ok(private.product_media_legacy_write(current_setting('c11.a')||'/products/c11-product/old.png'),'rolling release accepts old uploader in its tenant');
select ok(not private.product_media_legacy_write(current_setting('c11.b')||'/products/other/old.png'),'rolling release rejects foreign tenant path');
select ok(not private.product_media_legacy_write(current_setting('c11.a')||'/unexpected/path.png'),'rolling release rejects arbitrary storage scope');
insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict do nothing;
insert into storage.objects(bucket_id,name) values('product-images',current_setting('c11.a')||'/products/c11-product/legacy.png');
select ok(private.product_media_known(current_setting('c11.a'),'https://assets.example.test/storage/v1/object/public/product-images/'||current_setting('c11.a')||'/products/c11-product/legacy.png',null),'existing tenant gallery object remains valid after rollout');
select ok(not private.product_media_known(current_setting('c11.b'),'https://assets.example.test/storage/v1/object/public/product-images/'||current_setting('c11.a')||'/products/c11-product/legacy.png',null),'legacy recognition never grants foreign tenant ownership');
select ok(not has_table_privilege('authenticated','public.product_reviews','select'),'browser cannot read private Order/customer binding directly');
select ok(not has_table_privilege('authenticated','public.product_reviews','insert'),'browser cannot forge reviews');
select ok(not has_function_privilege('authenticated','public.product_review_token(text,text,uuid,jsonb)','execute'),'browser cannot impersonate actor through service RPC');
select ok(not has_function_privilege('anon','public.product_reviews_public(text,text,integer)','execute'),'public listing resolves tenant only on server');
set local role authenticated;
select throws_ok($$select pg_temp.c11_invite('pending')$$,'22023','Compra não elegível ou já avaliada.','cannot review before delivery/completion');
select set_config('c11.invite',pg_temp.c11_invite('one')::text,true);
select set_config('c11.token',current_setting('c11.invite')::jsonb->>'token',true);
select is(length(current_setting('c11.token')),64,'invitation is 256-bit opaque token');
select is(jsonb_array_length(public.product_reviews_source()->'eligible'),2,'eligible purchases use canonical Order/product/customer account');
reset role;
select is((select token_hash from private.product_review_tokens where order_id='c11-one'),encode(extensions.digest(current_setting('c11.token'),'sha256'),'hex'),'only token hash persisted');
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select pg_temp.c11_invite('one')$$,'22023','Compra indisponível.','cross-tenant invitation denied');
select is(jsonb_array_length(public.product_reviews_source()->'rows'),0,'tenant B source has no tenant A reviews');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.product_review_token(current_setting('c11.b'),current_setting('c11.token')),null::jsonb,'token bound to host-resolved tenant');
select is(public.product_review_token(current_setting('c11.a'),repeat('0',64)),null::jsonb,'invalid token uniform miss');
select ok(not (public.product_review_token(current_setting('c11.a'),current_setting('c11.token')) ?| array['customer_id','order_id','email','phone','document','notes','amount']),'public invitation excludes PII and Order/finance data');
select throws_ok($$select public.product_review_token(current_setting('c11.a'),current_setting('c11.token'),'c1100000-0000-4000-8000-000000000002','{"rating":5}')$$,'42501','Entre com a conta vinculada à compra.','shared token cannot be used by another account');
select throws_ok($$select public.product_review_token(current_setting('c11.a'),current_setting('c11.token'),'c1100000-0000-4000-8000-000000000003','{"rating":1.5}')$$,'22023','Nota/comentário inválidos; não inclua dados pessoais.','fractional rating rejected in database');
select throws_ok($$select public.product_review_token(current_setting('c11.a'),current_setting('c11.token'),'c1100000-0000-4000-8000-000000000003','{"rating":5,"verified_purchase":true}')$$,'22023','Avaliação inválida.','verified purchase cannot be forged');
select throws_ok($$select public.product_review_token(current_setting('c11.a'),current_setting('c11.token'),'c1100000-0000-4000-8000-000000000003','{"rating":5,"comment":"email@example.test"}')$$,'22023','Nota/comentário inválidos; não inclua dados pessoais.','contact information rejected');
reset role;
update private.product_review_tokens set expires_at=now()-interval '1 second' where order_id='c11-one';
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.product_review_token(current_setting('c11.a'),current_setting('c11.token')),null::jsonb,'expired token unusable');
reset role;
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('c11.old',current_setting('c11.token'),true);
select set_config('c11.token',pg_temp.c11_invite('one')->>'token',true);
select public.product_reviews_command('revoke','{"order_id":"c11-one","product_id":"c11-product"}');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.product_review_token(current_setting('c11.a'),current_setting('c11.old')),null::jsonb,'rotation invalidates previous token');
select is(public.product_review_token(current_setting('c11.a'),current_setting('c11.token')),null::jsonb,'revocation invalidates unconsumed token');
reset role;
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('c11.token',pg_temp.c11_invite('one')->>'token',true);
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select ok((public.product_review_token(current_setting('c11.a'),current_setting('c11.token'),'c1100000-0000-4000-8000-000000000003','{"rating":5,"comment":"<b>Ótima impressão!</b> 😀"}')->>'submitted')::boolean,'eligible authenticated customer submits pending review');
select throws_ok($$select public.product_review_token(current_setting('c11.a'),current_setting('c11.token'),'c1100000-0000-4000-8000-000000000003','{"rating":5}')$$,'22023','Avaliação já enviada.','single-use replay rejected');
select is((public.product_reviews_public(current_setting('c11.a'),'c11-product')->>'count')::integer,0,'pending is not public');
select is(public.product_reviews_public(current_setting('c11.a'),'c11-product')->>'average',null,'empty rating does not show misleading zero');
reset role;
select set_config('c11.review',(select id::text from public.product_reviews where order_id='c11-one'),true);
select is((select comment from public.product_reviews where order_id='c11-one'),'Ótima impressão! 😀','HTML stripped, accents and emoji preserved');
select is((select count(*)::integer from public.product_reviews where order_id='c11-one'),1,'one review per purchase/product');
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.c11_moderate('approve',current_setting('c11.review')::uuid);
select set_config('c11.token2',pg_temp.c11_invite('two')->>'token',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.product_review_token(current_setting('c11.a'),current_setting('c11.token2'),'c1100000-0000-4000-8000-000000000003','{"rating":1}');
select is((public.product_reviews_public(current_setting('c11.a'),'c11-product')->>'average')::numeric,5::numeric,'average includes approved only');
select is(public.product_reviews_public(current_setting('c11.a'),'c11-product')#>>'{rows,0,author}','M***','author anonymized by default');
select ok(not (public.product_reviews_public(current_setting('c11.a'),'c11-product')#>'{rows,0}' ?| array['customer_id','order_id','order_number','email','phone','document','name']),'public review DTO excludes PII and Order identifiers');
select set_config('c11.review2',(select id::text from public.product_reviews where order_id='c11-two'),true);
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.c11_moderate('reject',current_setting('c11.review2')::uuid);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is((public.product_reviews_public(current_setting('c11.a'),'c11-product')->>'average')::numeric,5::numeric,'rejected excluded from average');
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.c11_moderate('restore',current_setting('c11.review2')::uuid);
select is((select status from public.product_reviews where order_id='c11-two'),'pending','restore requires fresh moderation');
select pg_temp.c11_moderate('approve',current_setting('c11.review2')::uuid);
select pg_temp.c11_moderate('hide',current_setting('c11.review')::uuid);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is((public.product_reviews_public(current_setting('c11.a'),'c11-product')->>'average')::numeric,1::numeric,'hidden excluded from average');
select is((public.product_reviews_public(current_setting('c11.a'),'c11-product')->>'count')::integer,1,'public count includes approved only');
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.c11_moderate('restore',current_setting('c11.review')::uuid);
select pg_temp.c11_moderate('approve',current_setting('c11.review')::uuid);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is((public.product_reviews_public(current_setting('c11.a'),'c11-product')->>'average')::numeric,3::numeric,'new purchase permits second review; decimal aggregate correct');
select public.product_media_register(current_setting('c11.a'),'c1100000-0000-4000-8000-000000000001',current_setting('c11.a')||'/products/c11-product/'||repeat('a',64)||'.webp','https://assets.example.test/storage/v1/object/public/product-images/'||current_setting('c11.a')||'/products/c11-product/'||repeat('a',64)||'.webp',repeat('a',64),100);
select public.product_media_register(current_setting('c11.b'),'c1100000-0000-4000-8000-000000000002',current_setting('c11.b')||'/products/c11-other/'||repeat('b',64)||'.webp','https://assets.example.test/storage/v1/object/public/product-images/'||current_setting('c11.b')||'/products/c11-other/'||repeat('b',64)||'.webp',repeat('b',64),100);
select set_config('c11.foreign','https://assets.example.test/storage/v1/object/public/product-images/'||current_setting('c11.b')||'/products/c11-other/'||repeat('b',64)||'.webp',true);
select ok(not private.product_media_known(current_setting('c11.a'),current_setting('c11.foreign'),jsonb_build_object('gallery_images',jsonb_build_array(jsonb_build_object('url','https://example.test/a.png','alt',current_setting('c11.foreign'))))),'URL in alt cannot forge ownership');
select set_config('request.jwt.claims','{"sub":"c1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
update public.products set pricing_details=jsonb_build_object('gallery_images',jsonb_build_array(jsonb_build_object('url','https://example.test/a.png','is_primary',false,'position',0),jsonb_build_object('url','https://example.test/b.png','is_primary',true,'position',1)),'video_url','https://www.youtube.com/watch?v=abcdefghijk') where id='c11-product';
select is((select image_url from public.products where id='c11-product'),'https://example.test/b.png','explicit cover synchronized to canonical thumbnail');
select throws_ok($$update public.products set pricing_details=jsonb_build_object('gallery_images',jsonb_build_array(jsonb_build_object('url',current_setting('c11.foreign'),'position',0,'is_primary',true))) where id='c11-product'$$,'22023','Mídia inválida ou de outra empresa.','foreign tenant storage reference rejected');
select throws_ok($$update public.products set pricing_details=jsonb_build_object('gallery_images','[]'::jsonb,'video_url','https://evil.test/embed/1') where id='c11-product'$$,'22023','Vídeo inválido.','arbitrary iframe/provider URL rejected');
select throws_ok($$update public.products set pricing_details=jsonb_build_object('gallery_images',jsonb_build_array(jsonb_build_object('url','https://example.test/a.png','position',0,'is_primary',true),jsonb_build_object('url','https://example.test/b.png','position',1,'is_primary',true))) where id='c11-product'$$,'22023','Selecione uma única capa.','multiple covers rejected');
update public.products set pricing_details=jsonb_build_object('gallery_images','[]'::jsonb) where id='c11-product';
select is((select image_url from public.products where id='c11-product'),null,'removing last cover clears stale thumbnail');
select ok(exists(select 1 from public.audit_logs where company_id=current_setting('c11.a') and action='product_media.deleted'),'media removal audited');
select ok(exists(select 1 from public.audit_logs where company_id=current_setting('c11.a') and action='product_review.approved'),'review moderation audited');
select is((select count(*)::integer from public.financial_transactions where order_id in ('c11-one','c11-two')),0,'reviews never create financial movements');
select is((select paid_amount from public.orders where id='c11-one'),0::numeric,'review leaves Order financial state untouched');
insert into public.role_permissions(company_id,path,roles) values(current_setting('c11.a'),'/orders',array[]::text[]) on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select ok(not (public.product_reviews_source()->>'canOrder')::boolean,'explicit Orders denial respected');
select is(public.product_reviews_source()#>>'{rows,0,order_id}',null,'moderator without Orders access cannot see Order ID');
select is(jsonb_array_length(public.product_reviews_source()->'eligible'),0,'eligible Order list hidden without Orders access');
select throws_ok($$select pg_temp.c11_invite('pending')$$,'42501','Order access denied','invitation requires Orders permission');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('c11.a'),'/settings',array[]::text[]) on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select throws_ok($$select public.product_reviews_source()$$,'42501','Catalog access denied','catalog explicit denial blocks reviews');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select ok(public.product_review_rate('c11-test',2),'rate first attempt');
select ok(public.product_review_rate('c11-test',2),'rate second attempt');
select ok(not public.product_review_rate('c11-test',2),'rate excess rejected');
select * from finish();
rollback;
